<script lang="ts">
  import AppShell from "../components/AppShell.svelte";import Toast from "../components/Toast.svelte";import { radio } from "../lib/radio";import { api } from "../lib/api";import type{RadioStatus}from"../types";
  let message="",good=true,volume=0,lastVolume=-1,tintR=1,tintG=1,tintB=1,lastTint="";
  $: s=$radio;$: raw=s?.rawGpio||0;$: bits=raw.toString(2).padStart(11,"0");
  $: if(s){if(s.volume!==lastVolume){lastVolume=s.volume;volume=s.volume}const k=JSON.stringify(s.displayTint);if(k!==lastTint){lastTint=k;tintR=s.displayTint.r;tintG=s.displayTint.g;tintB=s.displayTint.b}}
  function notify(v:string,ok=true){message=v;good=ok;setTimeout(()=>message="",4000)}
  async function post(url:string,body?:unknown){try{await api(url,{method:"POST",body:body===undefined?undefined:JSON.stringify(body)})}catch(e){notify((e as Error).message,false)}}
  function virtual(field:string,value:number){if(!s)return;let mono=(raw>>10)&1,power=(raw>>9)&1,bt=(raw>>8)&1,band=(raw>>4)&15,display=raw&15;if(field==="mono")mono=value;if(field==="power")power=value;if(field==="bt")bt=value;if(field==="band")band=value;if(field==="display")display=value;post("/api/debug/gpio",{value:(mono<<10)|(power<<9)|(bt<<8)|(band<<4)|display})}
  async function reset(){await post("/api/debug/reset");notify("Temporary overrides cleared")}
  async function setChannel(id:string|null){await post("/api/debug/channel",{id})}
  async function setVolume(){await post("/api/debug/volume",{volume})}
  async function setTint(){await post("/api/debug/tint",{r:tintR,g:tintG,b:tintB})}
  async function calibrate(kind:string){await post("/api/tuner/calibrate",{kind})}
  async function invert(){if(s)await post("/api/tuner/invert",{invert:!s.tuner.calibration.invert})}
  async function system(url:string,text:string){if(confirm(text))await post(url)}
  const displayLabels:Record<string,string>={"auto-artwork":"Auto + artwork","auto-logo":"Auto logo","always-artwork":"Always + artwork","always-logo":"Always logo","off":"Off"};
</script>
<AppShell subtitle="Diagnostics"><main class="page">
  <section class="card"><h2>GPIO</h2><div class="bitline">{#each bits as bit,i}<span class:on={bit==="1"} class:control={i<3}>{bit}</span>{/each}</div><div class="decoded"><div><small>Power</small><b>{s?.power?"ON":"OFF"}</b></div><div><small>Mode</small><b>{s?.mode||"—"}</b></div><div><small>Band</small><b>{s?.tunerBand||0}</b></div><div><small>Display</small><b>{displayLabels[s?.displayMode||""]||s?.displayMode}</b></div><div><small>Raw</small><b>{raw}</b></div></div></section>
  <div class="grid"><section class="card"><h2>Current channel</h2><h3>{s?.channel?.name||"None"}</h3><p class="muted">{s?.metadata||s?.channel?.url||"—"}</p><button on:click={()=>setChannel(null)}>Return to tuner</button></section><section class="card"><h2>Volume</h2><div class="range"><input type="range" min="0" max="100" bind:value={volume} on:change={setVolume}><b>{volume}%</b></div></section></div>
  <section class="card"><h2>Virtual controls</h2><div class="controls"><div><small>Power</small><button on:click={()=>virtual("power",0)}>Off</button><button on:click={()=>virtual("power",1)}>On</button></div><div><small>Bluetooth</small><button on:click={()=>virtual("bt",0)}>Off</button><button on:click={()=>virtual("bt",1)}>On</button></div><div><small>Audio</small><button on:click={()=>virtual("mono",0)}>Mono</button><button on:click={()=>virtual("mono",1)}>Stereo</button></div></div><div class="controls"><div><small>Band</small>{#each s?.bands||[] as b}<button on:click={()=>virtual("band",b.hardware)}>{b.name}</button>{/each}</div><div><small>Display</small>{#each s?.displayOptions||[] as o}<button on:click={()=>virtual("display",o.bits)}>{o.label}</button>{/each}</div></div><div class="actions"><button class="primary" on:click={reset}>Reset everything to physical</button></div></section>
  <section class="card"><h2>Tuner</h2><div class="decoded"><div><small>Status</small><b>{s?.tuner.ready?"Ready":"Unavailable"}</b></div><div><small>Raw</small><b>{s?.tuner.latestRaw??"—"}</b></div><div><small>Min / Max</small><b>{s?.tuner.calibration.minAngle} / {s?.tuner.calibration.maxAngle}</b></div><div><small>Fraction</small><b>{s?.tuner.fraction?.toFixed(3)||"—"}</b></div></div><div class="needle"><i style={`left:${(s?.tuner.fraction||0)*100}%`}></i>{#each s?.tuner.channelsInBand||[] as c}<span title={c.name}></span>{/each}</div><p class="muted">{(s?.tuner.channelsInBand||[]).map(c=>c.name).join(" · ")||"No channels in band"}</p><div class="actions"><button on:click={()=>calibrate("min")}>Set min</button><button on:click={()=>calibrate("max")}>Set max</button><button on:click={invert}>Invert: {s?.tuner.calibration.invert?"on":"off"}</button></div></section>
  <div class="grid"><section class="card"><h2>Display override</h2><div class="actions"><button on:click={()=>post("/api/debug/logo-override",{ref:null})}>Normal</button><button on:click={()=>post("/api/debug/logo-override",{ref:"test-grid.png"})}>Test grid</button></div></section><section class="card"><h2>Display tint</h2><div class="range"><span>R</span><input type="range" min="0" max="1.5" step=".01" bind:value={tintR}><b>{tintR.toFixed(2)}</b></div><div class="range"><span>G</span><input type="range" min="0" max="1.5" step=".01" bind:value={tintG}><b>{tintG.toFixed(2)}</b></div><div class="range"><span>B</span><input type="range" min="0" max="1.5" step=".01" bind:value={tintB}><b>{tintB.toFixed(2)}</b></div><div class="actions"><button on:click={()=>{tintR=1;tintG=1;tintB=1;setTint()}}>Neutral</button><button on:click={()=>{tintR=1.15;tintG=.6;tintB=.3;setTint()}}>Ember</button><button class="primary" on:click={setTint}>Apply</button></div></section></div>
  <section class="card"><h2>Channel map</h2><div class="channel-grid">{#each s?.bands||[] as band}<div><h3>{band.name}</h3>{#each (s?.channels||[]).filter(c=>c.band===band.ordinal).sort((a,b)=>a.order-b.order) as channel}<button class:active={s?.channel?.id===channel.id} on:click={()=>setChannel(channel.id)}>{channel.name}</button>{/each}</div>{/each}</div></section>
  <section class="card"><h2>State</h2><pre>{JSON.stringify(s,null,2)}</pre></section>
  <section class="card"><h2>System</h2><div class="actions"><button class="danger" on:click={()=>system("/api/system/wifi-reset","Delete saved WiFi and reboot?")}>Reset WiFi</button><button class="danger" on:click={()=>system("/api/system/reboot","Reboot the radio?")}>Reboot</button></div></section>
</main><Toast {message} {good}/></AppShell>
<style>.bitline{display:flex;gap:.35rem;justify-content:center;flex-wrap:wrap}.bitline span{display:grid;place-items:center;width:34px;height:42px;border:1px solid var(--line);border-radius:7px;font:20px monospace;color:#596474}.bitline span.on{color:#ffc06d;border-color:#f09a5477;background:#f09a5413}.bitline span.control.on{color:var(--green);border-color:#69c28577}.decoded{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:.7rem;margin-top:1rem}.decoded div{padding:.65rem;background:#0b0e1377;border-radius:8px}.decoded small{display:block;color:var(--muted);margin-bottom:.25rem}.controls{display:flex;gap:1rem;flex-wrap:wrap;margin-bottom:.7rem}.controls>div{display:flex;gap:.35rem;align-items:center;flex-wrap:wrap}.controls small{margin-right:.3rem;color:var(--muted)}.range{display:grid;grid-template-columns:auto 1fr 52px;gap:.7rem;align-items:center;margin:.5rem 0}.needle{height:40px;background:#090b0f;border-radius:8px;position:relative;display:flex;overflow:hidden}.needle span{flex:1;border-right:1px solid #ffffff14}.needle i{position:absolute;top:2px;bottom:2px;width:3px;background:var(--accent);z-index:2}.channel-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}.channel-grid h3{color:var(--accent)}.channel-grid button{display:block;width:100%;text-align:left;margin:.25rem 0}.channel-grid button.active{color:var(--green);border-color:#69c28566}pre{font-size:.75rem;white-space:pre-wrap;color:var(--muted)}</style>
